func TestSplitChannel(t *testing.T) {
	cases := []struct {
		in     string
		pubsub string
		topic  string
		wantOk bool
	}{
		{"product-pubsub/product-topic", "product-pubsub", "product-topic", true},
		{"product-pubsub/deep/with/slashes", "product-pubsub", "deep/with/slashes", true},
		{"no-slash", "", "", false},
		{"/empty-pubsub", "", "", false},
		{"empty-topic/", "", "", false},
		{"", "", "", false},
	}
	for _, tc := range cases {
		pubsub, topic, err := SplitChannel(tc.in)
		if gotOk := err == nil; gotOk != tc.wantOk {
			t.Errorf("SplitChannel(%q) ok = %v, want %v (err %v)", tc.in, gotOk, tc.wantOk, err)
			continue
		}
		if tc.wantOk && (pubsub != tc.pubsub || topic != tc.topic) {
			t.Errorf("SplitChannel(%q) = %q, %q, want %q, %q", tc.in, pubsub, topic, tc.pubsub, tc.topic)
		}
	}
}
// Two groups carrying the same message id: a bare reference names both, so
// looking it up is refused rather than guessed.
func TestFindMessageBareRefAmbiguousAcrossGroups(t *testing.T) {
	doc := &Export{
		MessageGroups: map[string]MessageGroup{
			"one": {ID: "one", Messages: map[string]Message{"shared.event": {ID: "shared.event"}}},
			"two": {ID: "two", Messages: map[string]Message{"shared.event": {ID: "shared.event"}}},
		},
	}
	_, _, err := FindMessage(doc, "shared.event")
	if err == nil || !strings.Contains(err.Error(), "/messagegroups/one") || !strings.Contains(err.Error(), "/messagegroups/two") {
		t.Errorf("err = %v, want ambiguity naming both groups", err)
	}
}
func TestFindMessageEmptyExportDegradesToEmptyMaps(t *testing.T) {
	// An export with no collections at all is a valid empty registry.
	doc := &Export{}
	_, _, err := FindMessage(doc, "anything")
	var notFound *MessageNotFoundError
	if !errors.As(err, &notFound) {
		t.Errorf("err = %v, want MessageNotFoundError on the empty registry", err)
	}
}
func TestDefaultSchemaVersionXIDPinsTheDefaultVersion(t *testing.T) {
	doc := &Export{
		SchemaGroups: map[string]SchemaGroup{
			"sg": {ID: "sg", Schemas: map[string]Schema{
				"s": {ID: "s", Versions: map[string]Version{
					"3": {VersionID: "3", XID: "/schemagroups/sg/schemas/s/versions/3", IsDefault: true},
					"2": {VersionID: "2", XID: "/schemagroups/sg/schemas/s/versions/2"},
				}},
			}},
		},
	}
	xid, err := DefaultSchemaVersionXID(doc, "/schemagroups/sg/schemas/s")
	if err != nil {
		t.Fatal(err)
	}
	if xid != "/schemagroups/sg/schemas/s/versions/3" {
		t.Errorf("xid = %q, want the default version's xid", xid)
	}
	for _, bad := range []string{"not-an-xid", "/schemagroups/sg/schemas/unknown", "/schemagroups/unknown/schemas/s"} {
		if _, err := DefaultSchemaVersionXID(doc, bad); err == nil {
			t.Errorf("DefaultSchemaVersionXID(%q) err = nil, want SchemaNotFoundError", bad)
		} else {
			var notFound *SchemaNotFoundError
			if !errors.As(err, &notFound) {
				t.Errorf("DefaultSchemaVersionXID(%q) err = %v, want SchemaNotFoundError", bad, err)
			}
		}
	}
}
package xregistry
import (
	"fmt"
	"sort"
	"strings"
)
// FindMessage locates one message by reference — a bare message id
// (unique across groups) or a full /messagegroups/<gid>/messages/<mid>
// xid — and returns it with its group. Exported for display surfaces; the
// ambiguity and not-found failures are the typed errors.
func FindMessage(doc *Export, ref string) (*Message, *MessageGroup, error) {
	return findMessage(doc, ref)
}
func findMessage(doc *Export, ref string) (*Message, *MessageGroup, error) {
	if ref == "" {
		return nil, nil, fmt.Errorf("message reference is empty")
	}
	if xid, ok := strings.CutPrefix(ref, "/messagegroups/"); ok {
		gid, mid, ok := strings.Cut(xid, "/messages/")
		if !ok || gid == "" || mid == "" {
			return nil, nil, fmt.Errorf("message reference %q is not a message id or /messagegroups/<gid>/messages/<mid> xid", ref)
		}
		g, ok := doc.MessageGroups[gid]
		if !ok {
			return nil, nil, &MessageNotFoundError{Ref: ref}
		}
		m, ok := g.Messages[mid]
		if !ok {
			return nil, nil, &MessageNotFoundError{Ref: ref}
		}
		return &m, &g, nil
	}
	var found *Message
	var group *MessageGroup
	for i := range doc.MessageGroups {
		g := doc.MessageGroups[i]
		if m, ok := g.Messages[ref]; ok {
			if found != nil {
				xids := messageGroupXIDs(doc, ref)
				return nil, nil, fmt.Errorf("message reference %q is ambiguous: declared in groups %s", ref, strings.Join(xids, ", "))
			}
			mCopy, gCopy := m, g
			found, group = &mCopy, &gCopy
		}
	}
	if found == nil {
		return nil, nil, &MessageNotFoundError{Ref: ref}
	}
	return found, group, nil
}
// messageGroupXIDs names the groups carrying ref, for the ambiguity error.
func messageGroupXIDs(doc *Export, ref string) []string {
	var out []string
	for _, g := range doc.MessageGroups {
		if _, ok := g.Messages[ref]; ok {
			out = append(out, "/messagegroups/"+g.ID)
		}
	}
	sort.Strings(out)
	return out
}
// SplitChannel splits an endpoint channel into its pub/sub component and
// topic halves. The format belongs to the registry's conformance suite;
// this validates and fails naming the endpoint rather than accepting a
// half-parsed channel.
func SplitChannel(channel string) (pubsub, topic string, err error) {
	pubsub, topic, ok := strings.Cut(channel, "/")
	if !ok || strings.TrimSpace(pubsub) == "" || strings.TrimSpace(topic) == "" {
		return "", "", fmt.Errorf("channel %q is not <pubsub>/<topic>", channel)
	}
	return pubsub, topic, nil
}
// DefaultSchemaVersionXID pins a logical schema xid to its default
// version's xid — the immutable form a CloudEvent dataschema references.
// Exported for callers that already hold the export document and resolve
// display data (URLs, names) without a second round-trip.
func DefaultSchemaVersionXID(doc *Export, xid string) (string, error) {
	gid, sid, ok := splitSchemaXID(xid)
	if !ok {
		return "", &SchemaNotFoundError{XID: xid}
	}
	g, ok := doc.SchemaGroups[gid]
	if !ok {
		return "", &SchemaNotFoundError{XID: xid}
	}
	s, ok := g.Schemas[sid]
	if !ok {
		return "", &SchemaNotFoundError{XID: xid}
	}
	for _, v := range s.Versions {
		if v.IsDefault {
			return v.XID, nil
		}
	}
	return "", &SchemaNotFoundError{XID: xid}
}
// splitSchemaXID parses /schemagroups/<gid>/schemas/<sid>.
func splitSchemaXID(xid string) (gid, sid string, ok bool) {
	rest, ok := strings.CutPrefix(xid, "/schemagroups/")
	if !ok {
		return "", "", false
	}
	gid, sid, ok = strings.Cut(rest, "/schemas/")
	if !ok || gid == "" || sid == "" {
		return "", "", false
	}
	return gid, sid, true
}
package xregistry
// The served subset of the xRegistry 1.0-rc2x document model, decoded from
// GET /export. The registry is API-only and read-only (the service refuses
// filtering, inlining, and pagination), so the whole model arrives in one
// document and all resolution joins happen in memory against it.
//
// /export is the doc view: references are root-relative xids, collection
// urls and counts are absent, and for hasdocument resources the default
// Version's attributes are NOT repeated on the Resource. For messages —
// maxversions: 1 — every attribute therefore lives on the single implicit
// version, never on the message resource itself. Schemas, by contrast, are
// multi-version resources whose versions each carry isdefault.
// Export is the whole registry document from GET /export. The three
// collections are top-level group collections; an absent collection decodes
// as an empty map, so a caller never nil-checks.
type Export struct {
	SpecVersion   string                  `json:"specversion"`
	RegistryID    string                  `json:"registryid"`
	MessageGroups map[string]MessageGroup `json:"messagegroups"`
	Endpoints     map[string]Endpoint     `json:"endpoints"`
	SchemaGroups  map[string]SchemaGroup  `json:"schemagroups"`
}
// MessageGroup is one xRegistry message group carrying its message
// collection. The registry guarantees every published group is referenced
// by at least one channelled endpoint.
type MessageGroup struct {
	ID       string             `json:"messagegroupid"`
	Name     string             `json:"name,omitempty"`
	Messages map[string]Message `json:"messages"`
}
// Message is one message definition in the doc view. Definition attributes
// (envelope metadata, dataschemaxid) live on the single implicit version
// under Versions.
type Message struct {
	ID       string                     `json:"messageid"`
	Versions map[string]*MessageVersion `json:"versions"`
}
// MessageVersion is one version of a message definition. Messages have
// exactly one implicit version (versionid "1") carrying the definition.
type MessageVersion struct {
	VersionID        string                 `json:"versionid"`
	IsDefault        bool                   `json:"isdefault"`
	Envelope         string                 `json:"envelope,omitempty"`
	EnvelopeMetadata map[string]CEAttribute `json:"envelopemetadata,omitempty"`
	DataSchemaFormat string                 `json:"dataschemaformat,omitempty"`
	DataSchemaXID    string                 `json:"dataschemaxid,omitempty"`
	DataContentType  string                 `json:"datacontenttype,omitempty"`
}
// CEAttribute is one envelope metadata attribute. The registry constrains
// some attributes with a constant value; a message's CloudEvents type is
// the value of its `type` attribute.
type CEAttribute struct {
	Value       any    `json:"value"`
	Type        string `json:"type,omitempty"`
	Required    bool   `json:"required,omitempty"`
	Description string `json:"description,omitempty"`
}
// Endpoint is one registry endpoint: a role, the channel the endpoint
// speaks on, and the message groups allowed on it. Channel is
// <pubsub>/<topic>; the split helper in resolve.go owns the format.
type Endpoint struct {
	ID            string   `json:"endpointid"`
	Name          string   `json:"name,omitempty"`
	Usage         []string `json:"usage,omitempty"`
	Channel       string   `json:"channel,omitempty"`
	MessageGroups []string `json:"messagegroups,omitempty"`
}
// SchemaGroup is one schema group carrying schema resources.
type SchemaGroup struct {
	ID      string            `json:"schemagroupid"`
	Name    string            `json:"name,omitempty"`
	Schemas map[string]Schema `json:"schemas"`
}
// Schema is one schema resource. Versions carry isdefault; the default
// version URL is the immutable pin a CloudEvent dataschema references.
type Schema struct {
	ID       string             `json:"schemaid"`
	Format   string             `json:"format,omitempty"`
	Versions map[string]Version `json:"versions"`
}
// Version is one immutable schema version. XID is root-relative; the
// pinned URL is the base URL joined with it.
type Version struct {
	VersionID string `json:"versionid"`
	XID       string `json:"xid,omitempty"`
	IsDefault bool   `json:"isdefault"`
}
package template

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

const (
	// ScaffoldSchemaVersion is the newest scaffold.json schema this CLI
	// understands. Bump only for incompatible changes; additive fields do
	// not require a bump.
	ScaffoldSchemaVersion = 1

	// ScaffoldRelPath is where the scaffold record lives inside a project.
	ScaffoldRelPath = ".intropy/scaffold.json"

	// TemplateRoleLabel names the manifest label that declares what role a
	// template's output plays in a system. Its value is copied into the
	// scaffold record so later commands can tell support projects apart
	// from system blocks.
	TemplateRoleLabel = "intropy.io/template-role"

	// RoleSharedLibrary marks a scaffolded project that exists to be
	// referenced by sibling components (e.g. shared models). System
	// assembly must not treat it as a block.
	RoleSharedLibrary = "shared-library"

	// RoleSystemHost marks the scaffolded host project of an integration
	// system. System assembly must not treat it as a block.
	RoleSystemHost = "system-host"

	// TemplateBlockKindLabel names the manifest label that declares which
	// Intropy block a template scaffolds (e.g. "extractor"). Its value is
	// copied into the scaffold record so `sys create` can assemble the
	// system declaration from what each scaffold recorded.
	TemplateBlockKindLabel = "intropy.io/block-kind"

	// TemplateDataFlowLabel names the manifest label that declares the
	// block's data flow direction relative to the system ("in", "out",
	// or "both"). Recorded alongside the block kind.
	TemplateDataFlowLabel = "intropy.io/data-flow"

	// TemplateMessageParamsLabel names the manifest label that declares
	// which parameters carry message wiring, as a comma-separated list of
	// parameter names. A template without it declares no message
	// parameters: --subscribes against it is a usage error (R4), and its
	// parameters get no message suggestions however they are named.
	TemplateMessageParamsLabel = "intropy.io/message-params"

	// The BlockKind constants name the block kinds with a parse entry in
	// internal/system's blockParsers registry — the set `sys create`
	// assembles. Records carrying any other kind are skipped with a
	// warning.
	BlockKindExtractor     = "extractor"
	BlockKindLoader        = "loader"
	BlockKindTransactional = "transactional-integration"
	// BlockKindGateway is an extractor whose items are pushed to it over
	// HTTP: it publishes like an extractor, and its port is an endpoint it
	// exposes rather than a binding it sweeps.
	BlockKindGateway = "gateway"
	// BlockKindJob is scheduled work that runs to completion and wires no
	// message, port or endpoint: the catch-all for work no other kind
	// describes.
	BlockKindJob = "job"

	// Message direction values, derived from block kind. The mapping is
	// boundary-relative data-flow inverted: an extractor flows data in
	// from the external system and publishes messages, a loader flows out
	// and subscribes. MessageDirection is the one home of that flip.
	MessageDirectionPublish   = "publish"
	MessageDirectionSubscribe = "subscribe"
	MessageDirectionNone      = ""
)

var ErrScaffoldNotFound = errors.New("no " + ScaffoldRelPath + " found in current directory or any parent")

// Scaffold is the committed record of what `int create` rendered. Unlike
// CreateResult it carries no outputDir — the file's location is the project
// root — and it is written into the project so later commands (e.g. `sys
// create`) can re-fetch the exact template version.
type Scaffold struct {
	SchemaVersion int            `json:"schemaVersion"`
	Template      string         `json:"template"` // directory name in the template library repo
	Owner         string         `json:"owner"`
	Repo          string         `json:"repo"`
	Version       string         `json:"version"`
	Values        map[string]any `json:"values"`

	// Role is the value of the template's intropy.io/template-role label,
	// if any (e.g. "shared-library").
	Role string `json:"role,omitempty"`

	// BlockKind is the value of the template's intropy.io/block-kind
	// label, if any (e.g. "extractor").
	BlockKind string `json:"blockKind,omitempty"`

	// DataFlow is the value of the template's intropy.io/data-flow label,
	// if any ("in" or "out").
	DataFlow string `json:"dataFlow,omitempty"`

	// DependsOn lists the sibling projects this project's template declared
	// under spec.dependencies, whether the render created them or they
	// already existed.
	DependsOn []DependencyRecord `json:"dependsOn,omitempty"`
}

// DependencyRecord points at a sibling project a component depends on. Dir
// is slash-separated and relative to the component root (e.g. "../Acme.Models").
type DependencyRecord struct {
	Template string `json:"template"`
	Dir      string `json:"dir"`
}

func roleFromLabels(labels map[string]string) string {
	return labels[TemplateRoleLabel]
}

func blockKindFromLabels(labels map[string]string) string {
	return labels[TemplateBlockKindLabel]
}

// MessageDirection maps a template's block kind to the direction its
// message parameters wire: publish for producers, subscribe for
// consumers, None for kinds that talk with external systems directly
// (transactional integrations) and for unknown or absent kinds — the
// gate treats those as direction-neutral rather than guessing. A kind
// with no messaging must carry no message parameters for the flags to
// stay coherent; that check lives with the message-parameters gate.
func MessageDirection(kind string) string {
	switch kind {
	case BlockKindExtractor, BlockKindGateway:
		return MessageDirectionPublish
	case BlockKindLoader:
		return MessageDirectionSubscribe
	default:
		return MessageDirectionNone
	}
}

func dataFlowFromLabels(labels map[string]string) string {
	return labels[TemplateDataFlowLabel]
}

// WriteScaffold writes the scaffold record to <projectRoot>/.intropy/scaffold.json.
func WriteScaffold(projectRoot string, s Scaffold) error {
	path := filepath.Join(projectRoot, filepath.FromSlash(ScaffoldRelPath))
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data = append(data, '\n')
	if err := os.WriteFile(path, data, 0o644); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	return nil
}

// LoadScaffold reads and parses a scaffold.json file.
func LoadScaffold(path string) (*Scaffold, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read scaffold record %s: %w", path, err)
	}
	var s Scaffold
	if err := json.Unmarshal(data, &s); err != nil {
		return nil, fmt.Errorf("parse scaffold record %s: %w", path, err)
	}
	return &s, nil
}

// FindScaffold walks up from startDir looking for .intropy/scaffold.json.
// Returns the parsed record and the project root that contains it, or
// ErrScaffoldNotFound if the filesystem root is reached first.
func FindScaffold(startDir string) (*Scaffold, string, error) {
	abs, err := filepath.Abs(startDir)
	if err != nil {
		return nil, "", fmt.Errorf("absolute path: %w", err)
	}

	for {
		candidate := filepath.Join(abs, filepath.FromSlash(ScaffoldRelPath))
		if _, err := os.Stat(candidate); err == nil {
			s, err := LoadScaffold(candidate)
			if err != nil {
				return nil, "", err
			}
			return s, abs, nil
		} else if !os.IsNotExist(err) {
			return nil, "", fmt.Errorf("stat %s: %w", candidate, err)
		}

		parent := filepath.Dir(abs)
		if parent == abs {
			return nil, "", ErrScaffoldNotFound
		}
		abs = parent
	}
}

