package system

import (
	"fmt"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// parseBlock reads one scaffold record's kind-specific values into the
// component's wiring. The parser owns per-record validation only; every
// cross-component check stays in Assemble, gated on the component's shape.
type parseBlock func(e template.ScaffoldEntry, c *Component) error

// blockParsers is the set of block kinds Assemble accepts. Records with a
// kind absent from the registry are skipped with a warning naming the
// supported kinds. Adding a kind is a constant, a parser, and an entry here.
var blockParsers = map[string]parseBlock{
	template.BlockKindExtractor:     parseExtractor,
	template.BlockKindGateway:       parseGateway,
	template.BlockKindJob:           parseJob,
	template.BlockKindLoader:        parseLoader,
	template.BlockKindTransactional: parseTransactional,
}

// supportedKinds lists the registry keys sorted, for the unsupported-kind
// warning.
func supportedKinds() []string {
	kinds := make([]string, 0, len(blockParsers))
	for k := range blockParsers {
		kinds = append(kinds, k)
	}
	sort.Strings(kinds)
	return kinds
}

// parseExtractor reads the one message an extractor publishes. The message
// identity is the declaration; system assembly derives the channel and
// payload type from it.
func parseExtractor(e template.ScaffoldEntry, c *Component) error {
	published, err := parsePublishes(e, c)
	if err != nil || !published {
		return err
	}
	return parseSinglePort(e, c)
}

// parseGateway reads a gateway: the message it publishes, as an extractor's,
// and the endpoint it exposes with its path. The endpoint is required — the
// template that introduced the kind always records it — and it is not a file
// port, so it stays out of Ports. The path defaults to /<message>, the default
// the framework applies to a record without one.
func parseGateway(e template.ScaffoldEntry, c *Component) error {
	published, err := parsePublishes(e, c)
	if err != nil {
		return err
	}
	endpoint, err := template.RecordValue(e, template.KeyPort)
	if err != nil {
		return err
	}
	c.Endpoint = endpoint
	if published {
		c.EndpointPath = "/" + c.Message.Name
	}
	if _, ok := e.Values[template.KeyEndpointPath]; ok {
		path, err := template.RecordValue(e, template.KeyEndpointPath)
		if err != nil {
			return err
		}
		if !strings.HasPrefix(path, "/") {
			return fmt.Errorf("%s: values.%s is %q; a path starts with /", e.Path, template.KeyEndpointPath, path)
		}
		c.EndpointPath = path
	}
	return nil
}

// parsePublishes reads the one message a producing block publishes and the
// channel it publishes on; false when the message derives no contract.
func parsePublishes(e template.ScaffoldEntry, c *Component) (bool, error) {
	message, err := template.ReadPublishesMessage(e)
	if err != nil {
		return false, preScalarMessageRecord(err)
	}
	contract := template.PascalCase(message)
	if contract == "" {
		return false, nil
	}
	channel, err := template.ReadChannel(e)
	if err != nil {
		return false, err
	}
	if channel == "" {
		channel = message
	}
	c.channel = channel
	c.Topic = &TopicKey{Name: channel}
	c.topicContract = contract
	c.Message = &MessageWiring{Kind: MessagePublish, Name: message, Contract: contract}
	return true, nil
}

// parseLoader reads the messages a loader routes — its routes, or the one
// message a record without routes subscribes to — what it does with the rest
// of its topic, and the topic it declares. Assembly checks every routed
// message's producer publishes on that topic and fails if one does not.
func parseLoader(e template.ScaffoldEntry, c *Component) error {
	routes, err := template.ReadRoutes(e)
	if err != nil {
		if _, routed := e.Values[template.KeyRoutes]; routed {
			return err
		}
		return preScalarMessageRecord(err)
	}
	if c.Default, err = template.ReadDefault(e); err != nil {
		return err
	}
	if c.channel, err = template.ReadChannel(e); err != nil {
		return err
	}
	c.Routes = routes
	// The pipeline's message is subscribes; a record routing without it
	// predates the key and is typed by its first route.
	message, ok := template.SoftValue(e.Values, template.KeySubscribes)
	if !ok {
		message = routes[0].Message
	}
	c.Message = &MessageWiring{Kind: MessageSubscribe, Name: message}
	return parseSinglePort(e, c)
}

// preScalarMessageRecord reports a message-wiring read failure as the
// migration it is: a record scaffolded before the scalar message DSL carries
// nested blocks or legacy flat keys, and no fallback reads them. The guidance
// names both migration paths — set the scalar key, or re-scaffold.
func preScalarMessageRecord(err error) error {
	return fmt.Errorf("%w\nthis record predates the scalar message DSL: set values.publishes (extractor, gateway) or values.subscribes (loader) to the message name in the record's values, or re-scaffold the integration with a current template release", err)
}

func parseSinglePort(e template.ScaffoldEntry, c *Component) error {
	if _, ok := e.Values[template.KeyPort]; ok {
		port, err := template.RecordValue(e, template.KeyPort)
		if err != nil {
			return err
		}
		c.Port = port
		c.Ports = []string{port}
	} else {
		c.missingPort = true
	}
	return nil
}

// parseTransactional parses the wiring of a transactional block: exactly
// two ports, From before To, and no message. Both ports are required — a
// half-wired transactional block would render broken code.
func parseTransactional(e template.ScaffoldEntry, c *Component) error {
	from, err := template.RecordValue(e, template.KeyFromPort)
	if err != nil {
		return err
	}
	to, err := template.RecordValue(e, template.KeyToPort)
	if err != nil {
		return err
	}
	c.Ports = []string{from, to}
	return nil
}

// parseJob reads a job: nothing beyond its app id. A job wires no message,
// port or endpoint, so its record carries no wiring to read, and it joins
// the system as a component of its own.
func parseJob(template.ScaffoldEntry, *Component) error {
	return nil
}
package system

import "github.com/integrio-intropy/intropy-cli/internal/template"

// TopicKey identifies a topic within the system: the pub/sub component it
// lives on plus the topic name. Two scaffolds naming the same key declare
// the two halves of one contract. It aliases the canonical type in
// internal/template — there is one "which topic" concept across the CLI,
// shared by assembly and prompt-time facts.
type TopicKey = template.TopicKey

// Topic is one assembled topic: its key and the C# contract type its
// messages carry. The identifier it gets in the generated Topics class is
// derived by the template, not the CLI.
type Topic struct {
	TopicKey
	Contract string `json:"contract"`
}

// The two directions a message wiring can take. Extractors publish; loaders subscribe.
const (
	MessagePublish   = "publish"
	MessageSubscribe = "subscribe"
)

// Message is one message declaration in the system. Name doubles as the
// CloudEvents type; Contract is the .NET shared-project payload type derived
// from the message identity.
type Message struct {
	Name      string `json:"name"`
	Type      string `json:"type,omitempty"`
	Contract  string `json:"contract,omitempty"`
	Publisher string `json:"publisher,omitempty"`
	// Pubsub and Topic are the channel the message travels: its producer's.
	Pubsub string `json:"pubsub,omitempty"`
	Topic  string `json:"topic,omitempty"`
}

// Component is one assembled system block. Its wiring is shape-driven:
// Topic is nil for kinds without one, and Ports carries the named ports in
// the kind's order (From before To for transactional blocks).
//
// Topic is the derived transport channel for the component's message: the
// system pubsub and a topic named after the message. Subscribers receive the
// producer's channel during assembly. Its Pubsub stays empty until
// Model.UsePubsub names the system's.
type Component struct {
	AppID string    `json:"name"` // the Add<Kind> argument in the generated system class
	Kind  string    `json:"kind"` // a key of the blockParsers registry
	Topic *TopicKey `json:"-"`    // nil for kinds without a topic
	// Port is the single port of a topic block; empty for records that
	// predate it. Kept alongside Ports so the --output-json summary stays
	// additive-only.
	Port  string   `json:"port,omitempty"`
	Ports []string `json:"ports,omitempty"` // transactional blocks: exactly [from, to]
	// Endpoint is the HTTP port a gateway exposes and EndpointPath the path
	// it accepts items on; both empty for every other kind. The endpoint
	// shares the port namespace but is never a file port.
	Endpoint     string `json:"endpoint,omitempty"`
	EndpointPath string `json:"endpointPath,omitempty"`
	Path         string `json:"path"` // scaffold directory, for error messages

	// Message carries the component's message wiring: what it publishes or
	// subscribes by name. A routing subscriber's Message is its first route.
	Message *MessageWiring

	// Routes are a subscriber's rules in the order the sidecar evaluates
	// them, and Default what becomes of the events none of them matches.
	Routes  []template.Route
	Default string

	// channel is the topic the record declares it publishes or subscribes
	// on; empty for a record that predates the value.
	channel string

	// topicContract is the contract type of Topic, carried on the
	// component because topics dedupe across components: the model's
	// Topics list needs one contract per key, first seen wins.
	topicContract string
	// missingPort marks a topic-block record that predates the port value,
	// so Assemble can warn without failing the record.
	missingPort bool
}

// MessageWiring is the message-view wiring of one component.
type MessageWiring struct {
	Name string
	Kind string // MessagePublish or MessageSubscribe

	// Contract is the transitional .NET shared-project type recorded
	// alongside the message name; empty when the template no longer
	// records one.
	Contract string
}

// Port is one assembled port: the named edge a block reaches the outside
// world through. The declaration carries only the deployed transport shape;
// `sys create` resolves every port to a folder under the host's test/
// directory through the generated development definition. The identifier it
// gets in the generated Ports class is derived by the template, not the CLI.
type Port struct {
	Name string `json:"name"`
}

// Endpoint is one assembled gateway endpoint: the port it is named by and the
// path callers post to. The path is part of the system's declaration because
// the ingress in front of the host routes it.
type Endpoint struct {
	Name string `json:"name"`
	Path string `json:"path"`
}

// SharedLibrary is the workspace's contract project: referenced by the
// host, never declared as a component.
type SharedLibrary struct {
	Path string // scaffold directory
	Name string // project name; also the namespace and csproj basename
}

// Model is the assembled system declaration `sys create` generates code
// from. Name, ProjectName and SystemClass are filled in around the
// template render; Assemble leaves them empty.
type Model struct {
	Name        string // kebab-case system name
	ProjectName string // template-derived PascalCase name
	SystemClass string // template-derived ISystemDefinition class name
	Components  []Component
	Topics      []Topic    // sorted by (Pubsub, Name)
	Messages    []Message  // sorted by Name; the internal messagegroup
	Ports       []Port     // sorted by Name
	Endpoints   []Endpoint // gateways' HTTP ports, sorted by Name
	// Shared is the workspace's shared-library scaffold, nil when none
	// exists — valid for a topic-free system, and for a topic-bearing one
	// the host template scaffolds the contracts project as a dependency.
	Shared *SharedLibrary
}

// UsePubsub names the pub/sub of every channel Assemble left on the system's
// own — all of them, since a scaffold record never names one. The name needs
// the system, which assembly does not know: sys create derives it from its
// flag, sys update from the host's record.
func (m *Model) UsePubsub(pubsub string) {
	for i := range m.Components {
		if t := m.Components[i].Topic; t != nil && t.Pubsub == "" {
			t.Pubsub = pubsub
		}
	}
	for i := range m.Topics {
		if m.Topics[i].Pubsub == "" {
			m.Topics[i].Pubsub = pubsub
		}
	}
	for i := range m.Messages {
		if m.Messages[i].Topic != "" && m.Messages[i].Pubsub == "" {
			m.Messages[i].Pubsub = pubsub
		}
	}
}
package template

import (
	"sort"
)

// TopicKey identifies a pub/sub topic within a workspace: the pub/sub
// component it lives on plus the topic name. It is the key workspace facts
// dedupe on — two scaffold records naming the same key declare the two
// halves of one contract.
//
// It is the canonical "which topic" shape for the whole CLI —
// internal/system aliases it for assembly — and its JSON tags are the
// wire vocabulary `sys create --output json` already serves.
type TopicKey struct {
	Pubsub string `json:"pubsub"`
	Name   string `json:"topic"`
}

// WorkspaceFacts is the prompt-time view of what a workspace's scaffold
// records already declare: derived topics, the contract each carries,
// the external ports already named, the internal messages declared by
// scalar publishes values, plus the one organization the records agree on. Create
// flows derive parameter suggestions from it; it is built by callers that
// scan workspaces (internal/system) and consumed read-only by value
// resolution.
//
// Two fields are ambient inputs a caller seeds for the run rather than
// facts a scan derived: messageCandidates (external refs offered next to
// the internal messages) and messageParams (the template's message
// parameters, identified from the fetched manifest). Both live here so
// Suggest stays a single flat registry keyed by parameter name.
type WorkspaceFacts struct {
	// TopicKeys holds the distinct topic keys in use, sorted by
	// (Pubsub, Topic).
	TopicKeys []TopicKey

	// Ports holds the distinct external port names in use, sorted
	// lexicographically.
	Ports []string

	// organization is the single organization the workspace's block records
	// declare. Records naming different organizations demote the fact — a
	// component belongs to exactly one organization, so a workspace that
	// disagrees with itself has nothing to suggest.
	organization string

	// contracts maps a topic key to its recorded contract type. A key whose
	// records disagree on the contract is absent — a conflicted fact is no
	// fact, and callers treat absence as "no suggestion".
	contracts map[TopicKey]string

	// messages maps an internal message name (from scalar publishes values) to its
	// declared contract, when one was recorded.
	messages map[string]string

	// messageCandidates are external message refs offered as prompt
	// suggestions for message parameters, seeded by the caller.
	messageCandidates []string

	// messageParams names the template parameters that carry message
	// wiring, identified from the fetched manifest's label. Parameters
	// outside this set get no message suggestions whatever their name.
	messageParams map[string]bool

	// wiringDirection is the template's message direction, seeded by the
	// create flow from the template's block kind. It shades the candidate
	// pool and the wiring hint: a publishing template's pool carries only
	// external refs, since workspace-internal messages already have
	// producers (offering them would invite scaffolding a second
	// producer). The zero value — unknown direction — keeps the full pool
	// and the subscribe hint, matching direction-neutral behavior.
	wiringDirection string
}

// Organization returns the organization the workspace's block records
// agree on, or ("", false) when no record names one or they disagree.
func (f *WorkspaceFacts) Organization() (string, bool) {
	if f == nil || f.organization == "" {
		return "", false
	}
	return f.organization, true
}

// SetOrganization seeds the organization fact when the workspace has none.
// It is the caller's channel for context the records cannot carry — the
// resolved config's customer — and it never overrides a workspace-derived
// value: specific beats ambient. Call it before the facts feed Suggest.
func (f *WorkspaceFacts) SetOrganization(org string) {
	if f != nil && f.organization == "" {
		f.organization = org
	}
}

// ContractFor returns the contract type recorded for a topic key, or
// ("", false) when the key is unknown or its records conflict.
func (f *WorkspaceFacts) ContractFor(key TopicKey) (string, bool) {
	if f == nil {
		return "", false
	}
	c, ok := f.contracts[key]
	return c, ok
}

// AddMessageCandidates seeds external message candidates offered as prompt
// suggestions for message parameters. Internal message names come from the
// workspace's scalar publishes values; these join them.
func (f *WorkspaceFacts) AddMessageCandidates(refs []string) {
	if f == nil {
		return
	}
	f.messageCandidates = append(f.messageCandidates, refs...)
}

// MessageCandidates returns the deduplicated suggestion pool for message
// parameters: internal messages declared by the workspace's scalar publishes
// values plus the seeded external refs, merged and sorted. A publishing
// template's pool drops the internal messages — every one of them already
// has a producer, and a new producer is exactly what a publishing
// scaffold must not become.
func (f *WorkspaceFacts) MessageCandidates() []string {
	if f == nil {
		return nil
	}
	seen := map[string]bool{}
	var out []string
	if f.wiringDirection != MessageDirectionPublish {
		for name := range f.messages {
			if !seen[name] {
				seen[name] = true
				out = append(out, name)
			}
		}
	}
	for _, ref := range f.messageCandidates {
		if !seen[ref] {
			seen[ref] = true
			out = append(out, ref)
		}
	}
	sort.Strings(out)
	return out
}

// SetWiringDirection seeds the template's message direction. Ambient like
// SetOrganization and SetMessageParameters: it describes the template
// being scaffolded, not anything the workspace records declare.
func (f *WorkspaceFacts) SetWiringDirection(dir string) {
	if f != nil {
		f.wiringDirection = dir
	}
}

// WiringDirection returns the seeded message direction, empty when the
// template's kind gives no direction to derive.
func (f *WorkspaceFacts) WiringDirection() string {
	if f == nil {
		return ""
	}
	return f.wiringDirection
}

// SetMessageParameters names the template's message parameters. It is
// derived from the fetched manifest, so the prompt-time suggestion only
// fires for templates that declare message wiring — a template whose
// parameters merely share a name keeps working as before.
func (f *WorkspaceFacts) SetMessageParameters(names []string) {
	if f == nil {
		return
	}
	if f.messageParams == nil {
		f.messageParams = map[string]bool{}
	}
	for _, n := range names {
		f.messageParams[n] = true
	}
}

// IsMessageParameter reports whether the template's manifest identifies
// name as carrying message wiring.
func (f *WorkspaceFacts) IsMessageParameter(name string) bool {
	return f != nil && f.messageParams[name]
}

// ContractForMessage returns the contract a workspace record declared for
// an internal message name, or ("", false) when nothing declared it.
func (f *WorkspaceFacts) ContractForMessage(name string) (string, bool) {
	if f == nil {
		return "", false
	}
	c, ok := f.messages[name]
	return c, ok
}

// WorkspaceFactEntry is the slice of a scaffold record fact-building reads:
// which block the record scaffolds and the values it recorded. Keeping the
// input this narrow lets BuildWorkspaceFacts stay in this package — a
// caller-side adapter maps full scaffold records to entries, and the import
// graph never cycles back through the scanner.
type WorkspaceFactEntry struct {
	// BlockKind is the record's block kind ("extractor", "gateway",
	// "loader", "transactional-integration"); entries with any other kind
	// contribute nothing but their organization.
	BlockKind string

	// Values is the record's resolved parameter values.
	Values map[string]any
}

// BuildWorkspaceFacts indexes entries into workspace facts. It is
// deliberately lenient where Assemble is strict: entries with missing or
// mistyped wiring values are skipped rather than reported, because a
// suggestion aid must never fail an operation the records themselves would
// still allow. Organization is indexed from every entry with a block kind
// — a component's organization is not wiring — under the same conflict
// rule as contracts: one value wins, several demote the fact. The one
// cross-record rule it shares with Assemble is that conflicting contracts
// on one topic key demote the contract — suggesting either side of a
// conflict would bake a guess into the new record.
func BuildWorkspaceFacts(entries []WorkspaceFactEntry) *WorkspaceFacts {
	facts := &WorkspaceFacts{contracts: map[TopicKey]string{}, messages: map[string]string{}}
	type contractSighting struct {
		contract   string
		conflicted bool
	}
	sightings := map[TopicKey]*contractSighting{}
	seenTopic := map[TopicKey]bool{}
	seenPort := map[string]bool{}
	orgSeen := false
	orgConflicted := false

	indexTopic := func(key TopicKey, contract string) {
		if !seenTopic[key] {
			seenTopic[key] = true
			facts.TopicKeys = append(facts.TopicKeys, key)
		}
		if contract != "" {
			if s, seen := sightings[key]; seen {
				if s.contract != contract {
					s.conflicted = true
				}
			} else {
				sightings[key] = &contractSighting{contract: contract}
			}
		}
	}

	for _, e := range entries {
		if e.BlockKind == "" {
			continue
		}
		if org, ok := SoftValue(e.Values, KeyOrganization); ok {
			switch {
			case !orgSeen:
				orgSeen = true
				facts.organization = org
			case facts.organization != org:
				orgConflicted = true
			}
		}
		switch e.BlockKind {
		case BlockKindExtractor, BlockKindGateway:
			message, mok := SoftValue(e.Values, KeyPublishes)
			if mok {
				contract := PascalCase(message)
				// Pubsub left empty: a scaffold's message travels on the
				// system's pub/sub, named only once the system exists.
				indexTopic(TopicKey{Name: message}, contract)
				if _, seen := facts.messages[message]; !seen {
					facts.messages[message] = contract
				}
			}
			if port, ok := SoftValue(e.Values, KeyPort); ok && !seenPort[port] {
				seenPort[port] = true
				facts.Ports = append(facts.Ports, port)
			}
		case BlockKindLoader:
			if port, ok := SoftValue(e.Values, KeyPort); ok && !seenPort[port] {
				seenPort[port] = true
				facts.Ports = append(facts.Ports, port)
			}
		case BlockKindTransactional:
			for _, key := range []string{KeyFromPort, KeyToPort} {
				if port, ok := SoftValue(e.Values, key); ok && !seenPort[port] {
					seenPort[port] = true
					facts.Ports = append(facts.Ports, port)
				}
			}
		}

	}

	if orgConflicted {
		facts.organization = ""
	}
	for key, s := range sightings {
		if !s.conflicted {
			facts.contracts[key] = s.contract
		}
	}
	sort.Slice(facts.TopicKeys, func(i, j int) bool {
		if facts.TopicKeys[i].Pubsub != facts.TopicKeys[j].Pubsub {
			return facts.TopicKeys[i].Pubsub < facts.TopicKeys[j].Pubsub
		}
		return facts.TopicKeys[i].Name < facts.TopicKeys[j].Name
	})
	sort.Strings(facts.Ports)
	return facts
}

