package main

import (
	"sort"

	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
	"github.com/spf13/cobra"
)

// messageCmd groups the read-only discovery surface for messages: what the
// read-only xRegistry serves, plus what the workspace's scaffold records
// declare through scalar publishes values. It never writes anything.
var messageCmd = &cobra.Command{
	Use:   "message",
	Short: "Discover registry and workspace messages",
	Long: "Discover messages. 'message list' merges the read-only xRegistry with the messages the workspace's scaffold records declare through scalar publishes values; " +
		"'message show <ref>' prints one message's definition. Reading the registry requires registryUrl to be configured — there is no default",
}

// resolveRegistryURL layers the --registry-url flag over the config, the
// same precedence every other setting uses.
func resolveRegistryURL(flagURL string) (string, error) {
	cfg, err := config.Load()
	if err != nil {
		return "", err
	}
	url, err := cfg.Resolve(config.Flags{RegistryURL: flagURL}).RequireRegistryURL()
	if err != nil {
		return "", newUsageErrorf("%v", err)
	}
	return url, nil
}

// registryClient builds the xRegistry client from the resolved
// --registry-url. An unconfigured registry is a usage error naming every
// way to set it; there is no guessed default.
func registryClient(flagURL string) (*xregistry.Client, error) {
	url, err := resolveRegistryURL(flagURL)
	if err != nil {
		return nil, err
	}
	return newXRegistryClient(url)
}

func newXRegistryClient(url string) (*xregistry.Client, error) {
	return xregistry.New(url, xregistry.WithUserAgent(userAgent()))
}

// workspaceMessages indexes the publishes declarations under dir. Scan and
// parse warnings are non-fatal: a malformed sibling record must not hide
// the messages the rest of the workspace declares.
func workspaceMessages(dir string, warnf func(error)) []MessageEntry {
	entries, warnings := template.ListScaffolds(dir)
	for _, w := range warnings {
		warnf(w)
	}
	seen := map[string]bool{}
	var out []MessageEntry
	for _, e := range entries {
		message, err := template.ReadPublishesMessage(e)
		if err != nil {
			// Malformed records are skipped here — listing must show what is
			// resolvable; assembly is the surface that reports the record.
			continue
		}
		if seen[message] {
			continue
		}
		seen[message] = true
		out = append(out, MessageEntry{
			Message:  message,
			Source:   messageSourceWorkspace,
			Type:     message,
			Contract: template.PascalCase(message),
			Path:     e.Path,
		})
	}
	sortMessageEntries(out)
	return out
}

// sortMessageEntries orders a merged list: registry messages by ref, then
// workspace messages by name — the stable order both table and JSON echo.
func sortMessageEntries(entries []MessageEntry) {
	sort.SliceStable(entries, func(i, j int) bool {
		if entries[i].Source != entries[j].Source {
			return entries[i].Source == messageSourceRegistry
		}
		return entries[i].Message < entries[j].Message
	})
}

func init() {
	rootCmd.AddCommand(messageCmd)
}
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"

	"github.com/spf13/cobra"
)

type messageShowFlags struct {
	output      string
	registryURL string
}

var messageShowOpts messageShowFlags

var messageShowCmd = &cobra.Command{
	Use:   "show <ref> [dir]",
	Short: "Show one message's definition",
	Long: "Show one message's definition by reference — the bare message id or a /messagegroups/<gid>/messages/<mid> xid. " +
		"A workspace publish (a scalar publishes value in a scaffold record under dir, default current directory) resolves locally; everything else reads the xRegistry export. " +
		"The definition covers the envelope metadata, the producing channels, and the schema pin (the immutable default-version URL a CloudEvent dataschema references). " +
		"Use --output json for the same document machine-readable.",
	Args: usageArgs(cobra.RangeArgs(1, 2)),
	RunE: func(cmd *cobra.Command, args []string) error {
		ref := args[0]
		dir := "."
		if len(args) == 2 {
			dir = args[1]
		}
		if err := validateOutputFlag(messageShowOpts.output, "json", "plain"); err != nil {
			return err
		}
		if info, err := os.Stat(dir); err != nil {
			return fmt.Errorf("message show: %w", err)
		} else if !info.IsDir() {
			return newUsageErrorf("message show: %s is not a directory", dir)
		}

		// Workspace first: a local publish answers without the network, and
		// a name both sides declare is displayed with its local source.
		var wsWarnings []error
		for _, e := range workspaceMessages(dir, func(w error) { wsWarnings = append(wsWarnings, w) }) {
			if e.Message == ref {
				for _, w := range wsWarnings {
					fmt.Fprintln(cmd.ErrOrStderr(), "warning:", w)
				}
				return printMessage(cmd, &e, messageShowOpts.output)
			}
		}
		for _, w := range wsWarnings {
			fmt.Fprintln(cmd.ErrOrStderr(), "warning:", w)
		}

		client, err := registryClient(messageShowOpts.registryURL)
		if err != nil {
			return err
		}
		e, err := registryMessage(cmd.Context(), client, ref)
		if err != nil {
			return err
		}
		return printMessage(cmd, e, messageShowOpts.output)
	},
}

// printMessage writes one message: human rows to stdout, or the JSON
// document. Diagnostics never share the stdout stream.
func printMessage(cmd *cobra.Command, e *MessageEntry, output string) error {
	if output == "json" {
		enc := json.NewEncoder(cmd.OutOrStdout())
		enc.SetIndent("", "  ")
		return enc.Encode(e)
	}

	fmt.Fprintf(cmd.OutOrStdout(), "message:   %s\n", e.Message)
	fmt.Fprintf(cmd.OutOrStdout(), "source:    %s\n", e.Source)
	if e.Type != "" && e.Type != e.Message {
		fmt.Fprintf(cmd.OutOrStdout(), "type:      %s\n", e.Type)
	}
	if e.Envelope != "" {
		fmt.Fprintf(cmd.OutOrStdout(), "envelope:  %s\n", e.Envelope)
	}
	if e.Group != "" {
		fmt.Fprintf(cmd.OutOrStdout(), "group:     %s\n", e.Group)
	}
	if e.Path != "" {
		fmt.Fprintf(cmd.OutOrStdout(), "path:      %s\n", e.Path)
	}
	if e.Contract != "" {
		fmt.Fprintf(cmd.OutOrStdout(), "contract:  %s\n", e.Contract)
	}
	if len(e.Channels) > 0 {
		fmt.Fprintf(cmd.OutOrStdout(), "channels:  %s\n", strings.Join(e.Channels, ", "))
	}
	if e.DataSchema != "" {
		fmt.Fprintf(cmd.OutOrStdout(), "dataschema: %s\n", e.DataSchema)
	}
	if e.DataSchemaURL != "" {
		fmt.Fprintf(cmd.OutOrStdout(), "dataschemaurl: %s\n", e.DataSchemaURL)
	}
	for _, kv := range e.EnvelopeMeta {
		required := ""
		if kv.Required {
			required = " (required)"
		}
		value := "-"
		if kv.Value != "" {
			value = kv.Value
		}
		fmt.Fprintf(cmd.OutOrStdout(), "envelope %s: %s%s\n", kv.Name, value, required)
	}
	return nil
}

func init() {
	f := messageShowCmd.Flags()
	f.StringVarP(&messageShowOpts.output, "output", "o", "plain", flagUsageOutput)
	f.StringVar(&messageShowOpts.registryURL, "registry-url", "", flagUsageRegistryURL)
	messageCmd.AddCommand(messageShowCmd)
}
package main

// The registry half of the message commands: parse the export document
// into the shared MessageEntry shape. All joins happen in memory against
// one GET /export — the registry declares filtering and per-entity reverse
// lookups out of scope, so there is nothing smaller to fetch.

import (
	"context"
	"fmt"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

const (
	messageSourceRegistry  = "registry"
	messageSourceWorkspace = "workspace"
)

// registryMessages reads the export into entries, optionally narrowed to
// one group. Resolution failures that block wiring (an ambiguous or
// unreachable subscription channel) do not block listing: the table shows
// the channels it can see.
func registryMessages(ctx context.Context, client *xregistry.Client, group string) ([]MessageEntry, error) {
	doc, err := client.Export(ctx)
	if err != nil {
		return nil, err
	}

	ids := make([]string, 0, len(doc.MessageGroups))
	for id := range doc.MessageGroups {
		ids = append(ids, id)
	}
	sort.Strings(ids)

	var out []MessageEntry
	for _, gid := range ids {
		g := doc.MessageGroups[gid]
		if group != "" && gid != group {
			continue
		}
		for _, mid := range sortedMessageIDs(g) {
			m := g.Messages[mid]
			def := m.DefaultMessage()
			if def == nil {
				continue
			}
			e := MessageEntry{
				Message:  m.ID,
				Source:   messageSourceRegistry,
				Group:    gid,
				Type:     envelopeType(def),
				Envelope: def.Envelope,
				Channels: producerChannels(doc, gid),
			}
			if def.DataSchemaXID != "" {
				e.DataSchema = def.DataSchemaXID
				e.DataSchemaName = schemaName(def.DataSchemaXID)
				if xid, err := xregistry.DefaultSchemaVersionXID(doc, def.DataSchemaXID); err == nil {
					e.DataSchemaURL = joinURL(client.BaseURL(), xid)
				}
			}
			e.EnvelopeMeta = envelopeMetadata(def)
			out = append(out, e)
		}
	}
	return out, nil
}

// registryMessage finds exactly one message by reference — bare message id
// or /messagegroups/<gid>/messages/<mid> xid — for `message show`.
func registryMessage(ctx context.Context, client *xregistry.Client, ref string) (*MessageEntry, error) {
	doc, err := client.Export(ctx)
	if err != nil {
		return nil, err
	}
	msg, group, err := xregistry.FindMessage(doc, ref)
	if err != nil {
		return nil, err
	}
	def := msg.DefaultMessage()
	if def == nil {
		return nil, fmt.Errorf("message %q in group %s carries no definition attributes", ref, group.ID)
	}
	e := &MessageEntry{
		Message:  msg.ID,
		Source:   messageSourceRegistry,
		Group:    group.ID,
		Type:     envelopeType(def),
		Envelope: def.Envelope,
		Channels: producerChannels(doc, group.ID),
	}
	if def.DataSchemaXID != "" {
		e.DataSchema = def.DataSchemaXID
		e.DataSchemaName = schemaName(def.DataSchemaXID)
		if xid, err := xregistry.DefaultSchemaVersionXID(doc, def.DataSchemaXID); err == nil {
			e.DataSchemaURL = joinURL(client.BaseURL(), xid)
		}
	}
	e.EnvelopeMeta = envelopeMetadata(def)
	return e, nil
}

func sortedMessageIDs(g xregistry.MessageGroup) []string {
	ids := make([]string, 0, len(g.Messages))
	for id := range g.Messages {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	return ids
}

// producerChannels lists the producer endpoints' channels for one group,
// split-validated and rendered as <pubsub>/<topic>. A malformed channel is
// skipped here: listing must show what is resolvable, and assembly or
// --subscribes is the surface that reports the malformed endpoint.
func producerChannels(doc *xregistry.Export, groupID string) []string {
	want := "/messagegroups/" + groupID
	var out []string
	for _, e := range doc.Endpoints {
		if !usageHas(e.Usage, "producer") || !usageHas(e.MessageGroups, want) {
			continue
		}
		if pubsub, topic, err := xregistry.SplitChannel(e.Channel); err == nil {
			out = append(out, pubsub+"/"+topic)
		}
	}
	sort.Strings(out)
	return out
}

func usageHas(list []string, want string) bool {
	for _, s := range list {
		if s == want {
			return true
		}
	}
	return false
}

// envelopeType extracts the CloudEvents type from the envelope metadata.
func envelopeType(def *xregistry.MessageVersion) string {
	if attr, ok := def.EnvelopeMetadata["type"]; ok {
		if s, ok := attr.Value.(string); ok {
			return s
		}
	}
	return ""
}

// envelopeMetadata renders the envelope attributes sorted by name so the
// JSON document is stable across exports.
func envelopeMetadata(def *xregistry.MessageVersion) []kvHolder {
	names := make([]string, 0, len(def.EnvelopeMetadata))
	for n := range def.EnvelopeMetadata {
		names = append(names, n)
	}
	sort.Strings(names)
	out := make([]kvHolder, 0, len(names))
	for _, n := range names {
		a := def.EnvelopeMetadata[n]
		kv := kvHolder{Name: n, Required: a.Required}
		if s, ok := a.Value.(string); ok {
			kv.Value = s
		} else if a.Value != nil {
			kv.Value = fmt.Sprint(a.Value)
		}
		out = append(out, kv)
	}
	return out
}

// schemaName renders the schema xid's resource tail for the table column.
func schemaName(xid string) string {
	if i := strings.LastIndex(xid, "/schemas/"); i >= 0 {
		rest := xid[i+len("/schemas/"):]
		if j := strings.Index(rest, "/"); j >= 0 {
			return rest[:j]
		}
		return rest
	}
	return xid
}

// joinURL joins the registry base URL with a root-relative xid.
func joinURL(base, xid string) string {
	return strings.TrimSuffix(base, "/") + xid
}
package main

// The shared message model behind `message list` and `message show`: one
// shape for registry-served messages and workspace-declared ones, so the
// human table, the JSON document, and the show detail cannot drift apart.

// MessageEntry is one message as the message commands emit it, in JSON
// output. Source marks where the entry came from: "registry" (external,
// with its producing channels and schema pin) or "workspace" (internal, a
// publishes declaration in a scaffold record).
type MessageEntry struct {
	Message string `json:"message"`
	Source  string `json:"source"`

	Group          string     `json:"group,omitempty"`
	Type           string     `json:"type,omitempty"`
	Envelope       string     `json:"envelope,omitempty"`
	Channels       []string   `json:"channels,omitempty"` // <pubsub>/<topic>
	DataSchema     string     `json:"dataschema,omitempty"`
	DataSchemaURL  string     `json:"dataschemaurl,omitempty"`
	DataSchemaName string     `json:"dataschemaname,omitempty"`
	Contract       string     `json:"contract,omitempty"`
	Path           string     `json:"path,omitempty"` // workspace: the record's project directory
	EnvelopeMeta   []kvHolder `json:"envelopeMetadata,omitempty"`
}

// kvHolder is one envelope metadata attribute as JSON output: attribute
// name, value, and whether the envelope requires it.
type kvHolder struct {
	Name     string `json:"name"`
	Value    string `json:"value,omitempty"`
	Required bool   `json:"required,omitempty"`
}

