cat >> internal/xregistry/resolve.go <<'EOF'

// ProducerChannels lists the channels of the producer endpoints that carry
// groupID, split-validated, deduplicated and sorted as <pubsub>/<topic>. A
// malformed channel is skipped: the caller decides whether an empty answer
// is an error.
func ProducerChannels(doc *Export, groupID string) []string {
	want := "/messagegroups/" + groupID
	seen := map[string]bool{}
	var out []string
	for _, e := range doc.Endpoints {
		if !contains(e.Usage, "producer") || !contains(e.MessageGroups, want) {
			continue
		}
		pubsub, topic, err := SplitChannel(e.Channel)
		if err != nil {
			continue
		}
		channel := pubsub + "/" + topic
		if !seen[channel] {
			seen[channel] = true
			out = append(out, channel)
		}
	}
	sort.Strings(out)
	return out
}

func contains(list []string, want string) bool {
	for _, s := range list {
		if s == want {
			return true
		}
	}
	return false
}
EOF
