`

func createChannelExtractor(t *testing.T, sets map[string]any, message, channel string) (*Scaffold, error) {
	t.Helper()
	lib := newTestLibrary(t, "v9.9.9", map[string]string{
		"channel-extractor/template.yaml":           channelExtractorYAML,
