		"message-extractor/skeleton/README.md.tmpl": "{{ .publishes }}\n",
	})
	outDir := filepath.Join(t.TempDir(), "out")
	if sets == nil {
		sets = map[string]any{}
	}
	sets["integrationName"] = "x"
	tmplName := "channel-extractor"
	if v, ok := sets["_template"].(string); ok {
		tmplName = v
		delete(sets, "_template")
	}
	err := Create(context.Background(), CreateOptions{
		Template:         tmplName,
		OutputDir:        outDir,
		Version:          "v9.9.9",
		SetValues:        sets,
		NoInput:          true,
		Stderr:           io.Discard,
		Source:           lib.sourceOpts(t.TempDir(), nil),
		PublishesMessage: message,
		MessageChannel:   channel,
	})
	if err != nil {
		return nil, err
	}
	return LoadScaffold(filepath.Join(outDir, ScaffoldRelPath))
}

func TestCreateRecordsTheDecidedChannel(t *testing.T) {
	record, err := createChannelExtractor(t, nil, "se.ladok.studiedeltagande.antagning.created.v1", "ladok-events")
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	if got := record.Values[KeyChannel]; got != "ladok-events" {
		t.Errorf("values.channel = %v, want ladok-events", got)
	}
}

