	record, err := createChannelExtractor(t, nil, "invoice-created", "")
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	if record.Values[KeyChannel] != "invoice-created" || record.Values[KeyPayloadType] != "InvoiceCreated" {
		t.Errorf("values = %v, want InvoiceCreated on invoice-created", record.Values)
	}
}

// --set channel would be overwritten by the template's derivation; it is taken
// as the topic the channel derives from.
func TestCreateTakesSetChannelAsTheTopic(t *testing.T) {
	record, err := createChannelExtractor(t, map[string]any{KeyChannel: "orders"}, "order-created", "")
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	if got := record.Values[KeyChannel]; got != "orders" {
		t.Errorf("values.channel = %v, want orders", got)
	}
}

func TestCreateRefusesATopicContradictingTheDecidedChannel(t *testing.T) {
	_, err := createChannelExtractor(t, map[string]any{KeyTopic: "other"}, "m", "ladok-events")
	if !errors.Is(err, ErrChannelConflict) {
		t.Fatalf("err = %v, want ErrChannelConflict", err)
	}
	_, err = createChannelExtractor(t, map[string]any{KeyTopic: "a", KeyChannel: "b"}, "m", "")
	if !errors.Is(err, ErrChannelConflict) {
		t.Fatalf("err = %v, want ErrChannelConflict for topic and channel disagreeing", err)
	}
}

// A template without a topic parameter cannot record the decided channel.
func TestCreateRefusesADecidedChannelTheTemplateCannotRecord(t *testing.T) {
	_, err := createChannelExtractor(t, map[string]any{"_template": "message-extractor"}, "m", "ladok-events")
	if err == nil || !strings.Contains(err.Error(), "declares no topic parameter") {
		t.Fatalf("err = %v, want the missing topic parameter", err)
	}
}
