func TestMessageShowWorkspaceMessage(t *testing.T) {
	withRegistryURL(t, "http://127.0.0.1:1") // unreachable: a local publish must still show
	tmp := t.TempDir()
	t.Chdir(tmp)
	if err := os.MkdirAll(filepath.Join(tmp, ".intropy"), 0o755); err != nil {
		t.Fatal(err)
	}
	writeFileT(t, tmp+"/.intropy/scaffold.json", `{"schemaVersion":1,"template":"product-sink","owner":"o","repo":"r","version":"v1","blockKind":"extractor","values":{"appId":"product-sink","publishes":"product-exported"}}`+"\n")

	stdout, _ := runMessage(t, "show", "product-exported", "--output", "plain")
	if !strings.Contains(stdout.String(), "product-exported") || !strings.Contains(stdout.String(), "ProductExported") {
		t.Errorf("show = %q", stdout.String())
	}
}

func TestMessageShowWorkspaceDir(t *testing.T) {
	withRegistryURL(t, "http://127.0.0.1:1") // unreachable: the explicit dir should resolve locally
	tmp := t.TempDir()
	dir := filepath.Join(tmp, "workspace")
	if err := os.MkdirAll(filepath.Join(dir, ".intropy"), 0o755); err != nil {
		t.Fatal(err)
	}
	writeFileT(t, filepath.Join(dir, ".intropy", "scaffold.json"), `{"schemaVersion":1,"template":"product-sink","owner":"o","repo":"r","version":"v1","blockKind":"extractor","values":{"appId":"product-sink","publishes":"product-exported"}}`+"\n")
	t.Chdir(tmp)

	stdout, _ := runMessage(t, "show", "product-exported", dir, "--output", "plain")
	if !strings.Contains(stdout.String(), "product-exported") || !strings.Contains(stdout.String(), dir) {
		t.Errorf("show = %q", stdout.String())
	}
}

func TestMessageShowUnknownRef(t *testing.T) {
	withRegistryURL(t, messageRegistryURLFixture(t))
	t.Chdir(t.TempDir())

	stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
	resetRootIO(t, stdout, stderr)
	rootCmd.SetArgs([]string{"message", "show", "io.intropy.nosuch.message"})
	err := rootCmd.Execute()
	if err == nil {
		t.Fatal("expected a not-found error")
	}
	if !strings.Contains(err.Error(), "io.intropy.nosuch.message") {
		t.Errorf("error %q should name the ref", err)
	}
	_ = stdout
	_ = stderr
}

func TestMessageShowJSONOutput(t *testing.T) {
	withRegistryURL(t, messageRegistryURLFixture(t))
	t.Chdir(t.TempDir())

	stdout, _ := runMessage(t, "show", "io.intropy.maxbo.product.export", "--output", "json")
	var e MessageEntry
	if err := json.Unmarshal([]byte(stdout.String()), &e); err != nil {
		t.Fatalf("parse json: %v", err)
	}
	if len(e.EnvelopeMeta) == 0 {
		t.Errorf("envelope metadata missing in json: %+v", e)
	}
}

