package main

// The registry half of --publishes and --subscribes: a message the registry
// declares travels on its producer channel's topic, in both directions, so a
// component scaffolded from the registry lands where the registry says the
// message is. A message the registry does not know keeps the template's
// default topic, the message name.

import (
	"context"
	"errors"
	"fmt"
	"io"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/system"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

// resolveMessageChannel returns the topic message travels on according to the
// registry, or "" when the template's default applies: no message, no
// registry configured, a registry that does not declare the message, or one
// that names no producer channel for it. An unreachable registry is a warning,
// not a failure — an internal message must still scaffold offline — and the
// warning says which topic the component gets instead.
func resolveMessageChannel(ctx context.Context, stderr io.Writer, message string, sets map[string]any) (string, error) {
	if message == "" {
		return "", nil
	}
	explicit, err := explicitChannel(sets)
	if err != nil {
		return "", err
	}
	url, err := resolveRegistryURL("")
	if err != nil {
		return "", nil
	}
	client, err := newXRegistryClient(url)
	if err != nil {
		return "", err
	}
	doc, err := client.Export(ctx)
	if err != nil {
		fmt.Fprintf(stderr, "warning: %v\n%s is wired on the template's default topic; check the registry declares no other channel for it\n", err, message)
		return "", nil
	}
	return registryTopic(doc, message, explicit)
}

// explicitChannel reads the topic the user chose with --set. The templates
// take it as the topic parameter and derive the recorded channel from it, so
// channel is accepted as the same choice; naming both with different values is
// a usage error rather than a guess.
func explicitChannel(sets map[string]any) (string, error) {
	topic, _ := sets[template.KeyTopic].(string)
	channel, _ := sets[template.KeyChannel].(string)
	if topic != "" && channel != "" && topic != channel {
		return "", newUsageErrorf("--set topic=%s and --set channel=%s name different topics; set one", topic, channel)
	}
	if topic != "" {
		return topic, nil
	}
	return channel, nil
}

// registryTopic decides the topic for message from the registry export. The
// registry's producer channel decides; an explicit choice must be one of the
// producer channels' topics, and a message produced on several topics needs
// one. Only the topic half is returned: a scaffold record never names a
// pub/sub, which belongs to the system the component joins.
func registryTopic(doc *xregistry.Export, message, explicit string) (string, error) {
	_, group, err := xregistry.FindMessage(doc, message)
	var notFound *xregistry.MessageNotFoundError
	if errors.As(err, &notFound) {
		return "", nil
	}
	if err != nil {
		return "", newUsageErrorf("%v", err)
	}
	channels := xregistry.ProducerChannels(doc, group.ID)
	topics := channelTopics(channels)
	switch {
	case len(topics) == 0:
		return "", nil
	case explicit != "":
		for _, t := range topics {
			if t == explicit {
				return explicit, nil
			}
		}
		return "", newUsageErrorf("topic %q conflicts with the registry: %s is produced on %s\ndrop --set topic=%s to use the registry's channel, or correct the registry's producer endpoint",
			explicit, message, strings.Join(channels, ", "), explicit)
	case len(topics) == 1:
		return topics[0], nil
	default:
		return "", newUsageErrorf("message %q has %d producer channels in the registry: %s\npass --set topic=<topic> to choose one", message, len(topics), strings.Join(channels, ", "))
	}
}

// channelTopics projects <pubsub>/<topic> channels onto their distinct topics.
func channelTopics(channels []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, c := range channels {
		_, topic, err := xregistry.SplitChannel(c)
		if err != nil || seen[topic] {
			continue
		}
		seen[topic] = true
		out = append(out, topic)
	}
	sort.Strings(out)
	return out
}

// warnForeignProducers warns about each message the system publishes that the
// registry says another system's pub/sub produces. Producer and consumers
// live in one system for now, so such a message means a misnamed system or a
// second producer. It never fails: the registry may lag a rename, and the
// topic, which is what the broker routes on, is already the registry's. No
// registry, or nothing published, is nothing to check; an unreachable registry
// is one warning.
func warnForeignProducers(ctx context.Context, stderr io.Writer, m *system.Model) {
	var published []system.Message
	for _, msg := range m.Messages {
		if msg.Publisher != "" && msg.Pubsub != "" {
			published = append(published, msg)
		}
	}
	if len(published) == 0 {
		return
	}
	url, err := resolveRegistryURL("")
	if err != nil {
		return
	}
	client, err := newXRegistryClient(url)
	if err != nil {
		fmt.Fprintf(stderr, "warning: %v\n", err)
		return
	}
	doc, err := client.Export(ctx)
	if err != nil {
		fmt.Fprintf(stderr, "warning: published messages not checked against the registry: %v\n", err)
		return
	}
	for _, w := range foreignProducers(doc, published) {
		fmt.Fprintf(stderr, "warning: %s\n", w)
	}
}

// foreignProducers lists, as warnings, the messages whose registry producer
// channels name a pub/sub other than the one the system publishes them on. A
// message the registry does not know, or one with no producer channel, is not
// reported.
func foreignProducers(doc *xregistry.Export, published []system.Message) []string {
	var out []string
	for _, msg := range published {
		_, group, err := xregistry.FindMessage(doc, msg.Name)
		if err != nil {
			continue
		}
		channels := xregistry.ProducerChannels(doc, group.ID)
		if len(channels) == 0 {
			continue
		}
		own := false
		for _, c := range channels {
			if pubsub, _, err := xregistry.SplitChannel(c); err == nil && pubsub == msg.Pubsub {
				own = true
				break
			}
		}
		if !own {
			out = append(out, fmt.Sprintf("%s is produced on %s in the registry, but this system publishes it on %s\ncheck the system name, or whether another system already produces it",
				msg.Name, strings.Join(channels, ", "), msg.Pubsub))
		}
	}
	return out
}

// warnUnpublishedSubscription warns when a consumer is scaffolded for a message
// no component in its workspace publishes yet. It is a warning because the
// producer may be scaffolded next; sys create is where it becomes an error.
func warnUnpublishedSubscription(stderr io.Writer, facts *template.WorkspaceFacts, message string) {
	if message == "" {
		return
	}
	if _, published := facts.ContractForMessage(message); published {
		return
	}
	fmt.Fprintf(stderr, "warning: no component in this workspace publishes %s yet\n'intropy sys create' needs its producer in this system; subscribing to a message another system produces is not supported yet\n", message)
}

package system

import (
	"io"
	"path/filepath"
	"reflect"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// A record whose payloadType differs from the derivation — a contract renamed
// in Contracts, or named after its schema — types its message by the record,
// in the message list sys create renders Messages.cs from.
func TestAssembleTypesTheMessageByTheRecordedPayloadType(t *testing.T) {
	e := extractor("product-extractor", "product-extractor", "com.example.catalog.product.released.v1")
	e.Values[template.KeyPayloadType] = "ProductReleased"
	model, err := Assemble([]template.ScaffoldEntry{e}, discardWarnf)
	if err != nil {
		t.Fatalf("Assemble: %v", err)
	}
	if got := model.Messages[0].Contract; got != "ProductReleased" {
		t.Errorf("message contract = %q, want the recorded payloadType", got)
	}
	if got := model.Topics[0].Contract; got != "ProductReleased" {
		t.Errorf("topic contract = %q, want the recorded payloadType", got)
	}
}

// A record without payloadType keeps the derivation: invoice-created is
// InvoiceCreated on invoice-created.
func TestAssembleDerivesThePayloadTypeWithoutARecordedOne(t *testing.T) {
	model, err := Assemble([]template.ScaffoldEntry{extractor("invoices", "invoices", "invoice-created")}, discardWarnf)
	if err != nil {
		t.Fatalf("Assemble: %v", err)
	}
	m := model.Messages[0]
	if m.Contract != "InvoiceCreated" || m.Topic != "invoice-created" {
		t.Errorf("message = %+v, want InvoiceCreated on invoice-created", m)
	}
	if _, listed := ComponentEntry(model.Components[0])[template.KeyPublications]; listed {
		t.Error("a single-message producer's entry should carry no publications")
	}
}

// One extractor publishes several messages on one topic. Every one is a
// system message on the extractor's channel, the component entry lists them
// for the host, and a loader may route one published beside publishes.
func TestAssemblePublishesEveryPublicationOnTheRecordsChannel(t *testing.T) {
	e := channeled("sales-extractor", "com.example.sales.order.created.v1", "sales-events")
	e.Values[template.KeyPayloadType] = "OrderCreated"
	e.Values[template.KeyPublications] = []any{
		map[string]any{template.KeyMessage: "com.example.sales.order.created.v1"},
		map[string]any{template.KeyMessage: "com.example.sales.order.cancelled.v1", template.KeyPayloadType: "OrderCancelled"},
		map[string]any{template.KeyMessage: "com.example.sales.invoice.created.v1"},
	}
	l := routingLoader("cancellation-loader", "sales-events", "", template.Route{Message: "com.example.sales.order.cancelled.v1"})

	model, err := Assemble([]template.ScaffoldEntry{e, l}, discardWarnf)
	if err != nil {
		t.Fatalf("Assemble: %v", err)
	}
	got := map[string]string{}
	for _, m := range model.Messages {
		if m.Topic != "sales-events" || m.Publisher != "sales-extractor" {
			t.Errorf("message %+v, want sales-extractor on sales-events", m)
		}
		got[m.Name] = m.Contract
	}
	want := map[string]string{
		"com.example.sales.order.created.v1":   "OrderCreated",
		"com.example.sales.order.cancelled.v1": "OrderCancelled",
		"com.example.sales.invoice.created.v1": "ComExampleSalesInvoiceCreatedV1",
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("messages = %v, want %v", got, want)
	}
	wantNames := []any{
		"com.example.sales.order.created.v1",
		"com.example.sales.order.cancelled.v1",
		"com.example.sales.invoice.created.v1",
	}
	if entry := ComponentEntry(model.Components[0]); !reflect.DeepEqual(entry[template.KeyPublications], wantNames) {
		t.Errorf("publications = %#v, want %#v", entry[template.KeyPublications], wantNames)
	}
	if model.Topics[0].Contract != "" {
		t.Errorf("topic contract = %q, want none for a topic carrying several types", model.Topics[0].Contract)
	}
}

func TestAssemblePublicationsErrors(t *testing.T) {
	for _, tc := range []struct {
		name         string
		publications []any
		payloadType  string
		want         string
	}{
		{"publishes missing from the list",
			[]any{map[string]any{template.KeyMessage: "b"}}, "",
			`does not name the published message "a"`},
		{"a message twice",
			[]any{map[string]any{template.KeyMessage: "a"}, map[string]any{template.KeyMessage: "a"}}, "",
			`names message "a" twice`},
		{"entry without message",
			[]any{map[string]any{template.KeyPayloadType: "A"}}, "",
			"publications[0].message is missing"},
		{"list contradicts payloadType",
			[]any{map[string]any{template.KeyMessage: "a", template.KeyPayloadType: "Other"}}, "A",
			`types "a" as "Other", but values.payloadType is "A"`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			e := extractor("x", "x", "a")
			e.Values[template.KeyPublications] = tc.publications
			if tc.payloadType != "" {
				e.Values[template.KeyPayloadType] = tc.payloadType
			}
			_, err := Assemble([]template.ScaffoldEntry{e}, discardWarnf)
			if err == nil || !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("err = %v, want %q", err, tc.want)
			}
		})
	}
}

// Two producers may not type one message differently, recorded types included.
func TestAssembleRefusesConflictingRecordedPayloadTypes(t *testing.T) {
	a := extractor("a", "a", "order-created")
	b := extractor("b", "b", "order-created")
	b.Values[template.KeyPayloadType] = "OrderCreatedV2"
	_, err := Assemble([]template.ScaffoldEntry{a, b}, discardWarnf)
	if err == nil || !strings.Contains(err.Error(), "conflicting contracts") {
		t.Fatalf("err = %v, want the contract conflict", err)
	}
}

func multiPublisher(appID string, messages ...string) template.ScaffoldEntry {
	e := channeled(appID, messages[0], "sales-events")
	list := make([]any, len(messages))
	for i, m := range messages {
		list[i] = map[string]any{template.KeyMessage: m}
	}
	e.Values[template.KeyPublications] = list
	return e
}

// sys update refreshes publications like every other wiring key: a list the
// scaffold no longer implies leaves the stored entry.
func TestRefreshedEntryDropsPublicationsTheScaffoldNoLongerLists(t *testing.T) {
	before, err := Assemble([]template.ScaffoldEntry{multiPublisher("sales-extractor", "order-created", "order-cancelled")}, discardWarnf)
	if err != nil {
		t.Fatal(err)
	}
	stored := storedEntry(t, before.Components[0])
	if _, ok := stored[template.KeyPublications]; !ok {
		t.Fatalf("stored entry = %#v, want publications", stored)
	}
	after, err := Assemble([]template.ScaffoldEntry{channeled("sales-extractor", "order-created", "sales-events")}, discardWarnf)
	if err != nil {
		t.Fatal(err)
	}
	if got := refreshedEntry(stored, after.Components[0]); got[template.KeyPublications] != nil {
		t.Errorf("refreshed = %#v, want publications gone", got)
	}
}

// An orphan folded in by sys update brings every message it publishes.
func TestMergeWiringAddsEveryPublication(t *testing.T) {
	model, err := Assemble([]template.ScaffoldEntry{multiPublisher("sales-extractor", "order-created", "order-cancelled")}, discardWarnf)
	if err != nil {
		t.Fatal(err)
	}
	model.UsePubsub("sales-pubsub")
	plan := &updatePlan{hostDir: "host", baseline: map[string]any{}, orphans: model.Components}
	merged := map[string]any{}
	if err := mergeWiring(plan, merged); err != nil {
		t.Fatalf("mergeWiring: %v", err)
	}
	if got := len(merged["messages"].([]any)); got != 2 {
		t.Errorf("messages = %#v, want both publications", merged["messages"])
	}
}

// OnModel sees the assembled model with every channel on the system's pub/sub,
// before anything renders.
func TestPlanUpdateRunsOnModelWithTheSystemsPubsub(t *testing.T) {
	ws := t.TempDir()
	e := extractor(filepath.Join(ws, "sales-extractor"), "sales-extractor", "order-created")
	if err := template.WriteScaffold(e.Path, e.Scaffold); err != nil {
		t.Fatal(err)
	}
	host := template.Scaffold{Role: template.RoleSystemHost, Values: map[string]any{"name": "sales", "components": []any{}}}
	if err := template.WriteScaffold(filepath.Join(ws, "sales"), host); err != nil {
		t.Fatal(err)
	}
	var seen *Model
	if _, err := planUpdate(UpdateOptions{StartDir: ws, Stderr: io.Discard, OnModel: func(m *Model) { seen = m }}); err != nil {
		t.Fatal(err)
	}
	if seen == nil || len(seen.Messages) != 1 || seen.Messages[0].Pubsub != "sales-pubsub" {
		t.Fatalf("OnModel saw %+v, want order-created on sales-pubsub", seen)
	}
}

package template

import "strings"

// PascalCase derives the payload type name an internal message's schema
// projects to: strips the message to its letter-and-digit runs, drops
// separators (dots, dashes, underscores), and capitalizes each run.
// "orders" -> "Orders", "order-events" -> "OrderEvents". No singularization.
// Returns "" for an input with no letters or digits; callers gate on that.
// The template library applies the same derivation at render time and
// records it as payloadType; readers take the recorded value when there is
// one (ReadPublications), since a renamed contract changes the record, not
// the message. This derivation is the fallback for records without it.
func PascalCase(message string) string {
	var b strings.Builder
	capitalize := true
	for _, r := range message {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') {
			if capitalize {
				b.WriteRune(upper(r))
				capitalize = false
				continue
			}
			b.WriteRune(r)
			continue
		}
		capitalize = true
	}
	return b.String()
}

func upper(r rune) rune {
	if r >= 'a' && r <= 'z' {
		return r - ('a' - 'A')
	}
	return r
}
